,'REVISADO','APROBADO','t','t','t',11550000,null,'AGOSTO 2026',false),('0536',1,'tesoreria','2026-09-18','0753','DSE-4758','REVISADO','APROBADO','t','t','t',6300000,null,'AGOSTO 2026',false),('0537',1,'tesoreria','2026-09-18','0752','DSE-4757','REVISADO','APROBADO','t','t','t',3450000,null,'AGOSTO 2026',false),('0539',1,'tesoreria','2026-09-21','0758','DSE-4762','REVISADO','APROBADO','t','t','t',3450000,null,'AGOSTO 2026',false),('0540',1,'tesoreria','2026-09-21','0764','DSE-4763','REVISADO','APROBADO','t','t','t',3450000,null,'AGOSTO 2026',false),('0549',1,'tesoreria','2026-09-21','0755','DSE-4771','REVISADO','APROBADO','t','t','t',11550000,null,'AGOSTO 2026',false),('0550',1,'tesoreria','2026-09-21','0714','DSE-4778','REVISADO','APROBADO','t','t','t',6300000,null,'AGOSTO 2026',false),('0551',1,'tesoreria','2026-09-21','0731','DSE-4767','REVISADO','APROBADO','t','t','t',8400000,null,'AGOSTO 2026',false),('0553',1,'tesoreria','2026-09-21','0754','DSE-4761','REVISADO','APROBADO','t','t','t',3450000,null,'AGOSTO 2026',false),('0554',1,'tesoreria','2026-09-21','0760','DSE-4772','REVISADO','APROBADO','t','t','t',3450000,null,'AGOSTO 2026',false),('0576',1,'tesoreria','2026-09-09','0678','DSE-4705','REVISADO','APROBADO','t','t','t',5000000,null,'AGOSTO 2026',false),('0583',1,'subgerencia',null,'0781',null,null,null,'f','f','f',2000000,null,'AGOSTO 2026',false),('0584',1,'tesoreria','2026-09-23','0746','DSE-4797','REVISADO','APROBADO','t','t','t',7700000,7700000,'AGOSTO 2026',false),('0585',1,'subgerencia',null,'0822',null,null,null,'f','f','f',6300000,6300000,'SEPTIEMBRE 2026',false),('0590',1,'tesoreria','2026-09-23','0784','DSE-4809','REVISADO','APROBADO','t','t','t',4200000,4200000,'AGOSTO 2026',false),('0596',1,'tesoreria','2026-09-21','0769','DSE-4773','REVISADO','APROBADO','t','t','t',4200000,4200000,'AGOSTO 2026',false),('0602',1,'tesoreria','2026-09-25','0806','DSE-4822','REVISADO','APROBADO','t','t','t',6545000,6545000,'AGOSTO 2026',false),('0603',1,'tesoreria','2026-09-23','0762','DSE-4780','REVISADO','APROBADO','t','t','t',4760000,4760000,'AGOSTO 2026',false),('0604',1,'tesoreria','2026-09-25','0810','DSE-4823','REVISADO','APROBADO','t','t','t',6545000,6545000,'AGOSTO 2026',false),('0606',1,'subgerencia',null,'0828',null,null,null,'f','f','f',3360000,3360000,'SEPTIEMBRE 2026',false),('0607',1,'subgerencia',null,'0823',null,null,null,'f','f','f',3360000,3360000,'SEPTIEMBRE 2026',false),('0610',1,'subgerencia',null,'0820',null,null,null,'f','f','f',6300000,6300000,'SEPTIEMBRE 2026',false)
) v(num,pago,etapa,fe,rad,fac,sup,sec,notif,pres,cor,val,setval,hoja,doble) loop
  select c.id, c.etapa, (select count(*) from cc_movimientos m where m.cuenta_id=c.id) into cid, e, n
    from cc_cuentas c join cc_contratos k on k.id=c.contrato_id where k.numero_contrato=x.num and c.num_pago=x.pago;
  if cid is null then raise exception 'No existe la cuenta % pago %', x.num, x.pago; end if;
  if e<>'contratista' or n>0 then raise exception 'La cuenta % pago % ya tiene movimientos', x.num, x.pago; end if;
  fd := x.fe::date; ts := coalesce((x.fe||' 12:00:00-05')::timestamptz, now());
  update cc_cuentas set etapa=x.etapa, etapa_desde=ts,
    sp_estado='Aprobado', sp_fecha=fd-2, ct_estado='Aprobado', ct_fecha=fd-1,
    radicado=x.rad, factura=x.fac,
    sg_estado = case when x.etapa in ('tesoreria','supervision') then 'Aprobado' else 'Pendiente' end,
    sg_fecha  = case when x.etapa in ('tesoreria','supervision') then fd end,
    sup_estado= case when x.etapa='tesoreria' then 'Aprobado' else 'Pendiente' end,
    sup_fecha = case when x.etapa='tesoreria' then fd end,
    secop_estado = case when upper(coalesce(x.sec,'')) like 'APRO%' then 'Aprobado' else 'Pendiente' end,
    secop_fecha  = case when upper(coalesce(x.sec,'')) like 'APRO%' then fd end,
    sg_notificado=(x.notif='t'), sg_presupuesto=(x.pres='t'), sg_correo=(x.cor='t'),
    valor = coalesce(x.setval, valor),
    actualizado_en=now(), actualizado_por='Migración – Excel Subgerencia'
  where id=cid;
  if fd is not null then
    insert into cc_movimientos (cuenta_id,accion,etapa_origen,etapa_destino,fecha,motivo,detalle,usuario_nombre,usuario_proceso) values
    (cid,'migracion','salud_publica','contratacion',ts - interval '2 days','Migración – aprobada por Salud Pública (fecha asignada: 2 días antes de la fecha de Subgerencia)','{}'::jsonb,'Migración – Excel Subgerencia','superadmin'),
    (cid,'migracion','contratacion','subgerencia',ts - interval '1 day','Migración – aprobada por Contratación (fecha asignada: 1 día antes de la fecha de Subgerencia)','{}'::jsonb,'Migración – Excel Subgerencia','superadmin');
  end if;
  insert into cc_movimientos (cuenta_id,accion,etapa_origen,etapa_destino,fecha,motivo,detalle,usuario_nombre,usuario_proceso)
  values (cid,'migracion',case when fd is null then 'contratista' else 'subgerencia' end,x.etapa,ts,
    'Migración – Excel Subgerencia (hoja '||x.hoja||', radicado '||x.rad||')'||case when x.doble then ' · cobro de dos meses' else '' end,
    jsonb_strip_nulls(jsonb_build_object('hoja',x.hoja,'radicado',x.rad,'factura',x.fac,'supervisor',x.sup,'secop',x.sec,'valor_excel',x.val,'notificacion',x.notif,'presupuesto',x.pres,'correo',x.cor,'fecha',x.fe)),
    'Migración – Excel Subgerencia','superadmin');
end loop;
-- recalcular los pagos pendientes de los contratos cuyo valor cambió
for r in select k.id, k.numero_contrato, k.valor_total from cc_contratos k where k.numero_contrato in ('0327','0397','0398','0400','0411','0414','0584','0585','0590','0596','0602','0603','0604','0606','0607','0610') loop
  select coalesce(sum(valor),0) into saldo from cc_cuentas c where c.contrato_id=r.id and exists(select 1 from cc_movimientos m where m.cuenta_id=c.id);
  saldo := r.valor_total - saldo;
  select count(*) into cnt from cc_cuentas c where c.contrato_id=r.id and not exists(select 1 from cc_movimientos m where m.cuenta_id=c.id);
  if cnt=0 or saldo<0 then resumen := resumen || ' AVISO ' || r.numero_contrato || ' saldo=' || saldo || ' pendientes=' || cnt || ';'; continue; end if;
  base := floor(saldo/cnt); i := 0;
  for cid in select c.id from cc_cuentas c where c.contrato_id=r.id and not exists(select 1 from cc_movimientos m where m.cuenta_id=c.id) order by c.num_pago loop
    i := i+1;
    update cc_cuentas set valor = case when i=cnt then saldo-base*(cnt-1) else base end where id=cid;
  end loop;
  resumen := resumen || ' ' || r.numero_contrato || ':' || cnt || 'x' || base || ';';
end loop;
perform set_config('cc.rpc','',true);
select resumen || ' | ETAPAS ' || string_agg(etapa||'='||c, ', ') into resumen from (select etapa, count(*) c from cc_cuentas group by etapa order by 1) z;
if resumen like '%AVISO%' then raise exception 'Abortado: %', resumen; end if;
raise notice 'RESUMEN: %', resumen;
end $$;